func (w *rw0) Header() http.Header {
	return (*rwState)(w).doHeader()
}
func (w *rw0) WriteHeader(code int) {
	(*rwState)(w).doWriteHeader(code)
}
func (w *rw0) Write(b []byte) (int, error) {
	return (*rwState)(w).doWrite(b)
}

